import{_ as t,c as r,o as a,ag as i}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Irregularpedia","description":"","frontmatter":{"layout":"home","title":"Irregularpedia","hero":{"name":"Irregularpedia","text":"IrregularChat Knowledge Base","tagline":"Community-driven resources for security, privacy, research, and technology","actions":[{"theme":"brand","text":"Browse Wiki","link":"/general/"},{"theme":"alt","text":"IrregularChat Login","link":"https://sso.irregularchat.com"},{"theme":"alt","text":"Forum","link":"https://forum.irregularchat.com"}]},"features":[{"title":"Research & OSINT","details":"Open source intelligence, research methodologies, datasets, and analytical frameworks.","link":"/research/"},{"title":"AI & Autonomy","details":"LLM guides, AI ethics, prompt engineering, and autonomous systems resources.","link":"/ai-ml/"},{"title":"Information Warfare","details":"TAAW methodology, influence operations, COG analysis, and strategic communications.","link":"/general/information-warfare"},{"title":"Unmanned Systems","details":"sUAS operations, counter-UAS, FPV drones, and drone deployment guides.","link":"/general/unmanned-systems"},{"title":"Certifications & Learning","details":"Military credentialing, certification guides, and professional development resources.","link":"/general/certifications-and-learning"},{"title":"Military & Career","details":"Leaving service, SSC, evaluations, awards, promotion boards, and career advice.","link":"/general/military-and-career"},{"title":"RF/SDR/Communications","details":"Software defined radio, DragonOS, Flipper Zero, HAM radio, and RF guides.","link":"/radio/"},{"title":"Server & Infrastructure","details":"Self-hosting Matrix, Ansible automation, Docker deployments, and cloud setup.","link":"/server-guides/"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function n(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="welcome-to-irregularchat" tabindex="-1">Welcome to IrregularChat <a class="header-anchor" href="#welcome-to-irregularchat" aria-label="Permalink to &quot;Welcome to IrregularChat&quot;">​</a></h1><p>The <strong>IrregularChat</strong> Community of Interest (COI) is where tech enthusiasts, researchers, and innovators converge. This wiki is a dynamic space to discuss the latest in technology, share knowledge, and collaborate on projects.</p><p><em>Embrace a spirit of professional impatience and be ready to break down silos!</em></p><h2 id="rules-of-engagement" tabindex="-1">Rules of Engagement <a class="header-anchor" href="#rules-of-engagement" aria-label="Permalink to &quot;Rules of Engagement&quot;">​</a></h2><p>For the full list and community FAQ see the <a href="https://forum.irregularchat.com/t/irregularchat-community-faq-guidelines/4" target="_blank" rel="noreferrer">IrregularChat Forum</a>.</p><ol><li>Leave your rank and ego at the door.</li><li>Stay on topic to maintain focus. Mark jokes and sarcasm with <code>/j</code> or <code>/s</code>. Do NOT joke about leaking or spilling classified information. Others will report this action to their S/G/J2.</li><li>Avoid sharing confidential, personally identifiable information (PII) or classified information. Encryption does not make it permissible. <ol><li>Navigate content using the appropriate levels and direct users to relevant content locations.</li></ol></li><li>Chatham House Rule used throughout, unless stated otherwise. Participants can use information shared but must not reveal the source or identity of the speaker outside of the IrregularChat Community.</li><li>Don&#39;t be disrespectful to members.</li><li>Engage with the Wiki and Forum: <ol><li>Utilize the wiki for resources. If you find gaps, fill them in and share them in the chat.</li><li>Notice inaccuracies or missing information? Lead the effort to correct and enhance it.</li><li>If you encounter a missing page, take the initiative to create it.</li></ol></li></ol><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Action</th></tr></thead><tbody><tr><td>1. Login</td><td><a href="https://sso.irregularchat.com" target="_blank" rel="noreferrer">IrregularChat Login</a> (login required)</td></tr><tr><td>2. GitHub</td><td><a href="https://github.com/orgs/irregularchat/dashboard" target="_blank" rel="noreferrer">IrregularChat GitHub</a> (login required, send GitHub username to sac)</td></tr><tr><td>3. Explore</td><td>Browse this wiki using search or navigation</td></tr><tr><td>4. Contribute</td><td>Edit pages and share your knowledge</td></tr></tbody></table><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><h3 id="key-resources" tabindex="-1">Key Resources <a class="header-anchor" href="#key-resources" aria-label="Permalink to &quot;Key Resources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Links</th></tr></thead><tbody><tr><td>Learning</td><td><a href="/general/learning.html">Resources</a> • <a href="/general/certifications.html">Certifications</a></td></tr><tr><td>Research</td><td><a href="https://researchtools.net" target="_blank" rel="noreferrer">Research Tools</a> • <a href="/research/research-datasets.html">Datasets</a></td></tr><tr><td>AI/ML</td><td><a href="/ai-ml/ai-resources.html">AI Resources</a> • <a href="/ai-ml/">LLM Guides</a></td></tr><tr><td>Business</td><td><a href="/general/business.html">Business Tools</a></td></tr><tr><td>Security</td><td><a href="/cybersecurity/">Cybersecurity</a> • <a href="/privacy/">Privacy</a></td></tr></tbody></table><h3 id="community-hub" tabindex="-1">Community Hub <a class="header-anchor" href="#community-hub" aria-label="Permalink to &quot;Community Hub&quot;">​</a></h3><ul><li><a href="https://forum.irregularchat.com/c/general/4" target="_blank" rel="noreferrer">Technology Discussions</a></li><li><a href="https://forum.irregularchat.com/tag/ai" target="_blank" rel="noreferrer">AI/ML Discussions</a></li><li><a href="https://forum.irregularchat.com/tag/business" target="_blank" rel="noreferrer">Business Discussions</a></li><li><a href="/general/unmanned-systems.html">Unmanned Systems</a></li><li><a href="/server-guides/">Server Guides</a></li></ul><h2 id="sharing-content" tabindex="-1">Sharing Content <a class="header-anchor" href="#sharing-content" aria-label="Permalink to &quot;Sharing Content&quot;">​</a></h2><h3 id="before-posting" tabindex="-1">Before Posting <a class="header-anchor" href="#before-posting" aria-label="Permalink to &quot;Before Posting&quot;">​</a></h3><ol><li><strong>Search first</strong> - Check the wiki and <a href="https://forum.irregularchat.com" target="_blank" rel="noreferrer">Forum</a> before sharing</li><li><strong>Add context</strong> - Share context, not just links</li><li><strong>Use tags</strong> - Use #tagged categories for organization</li><li><strong>Scan files</strong> - Use <a href="https://www.virustotal.com/gui/home/upload" target="_blank" rel="noreferrer">VirusTotal</a> for any downloads</li></ol><h3 id="bypassing-paywalls" tabindex="-1">Bypassing Paywalls <a class="header-anchor" href="#bypassing-paywalls" aria-label="Permalink to &quot;Bypassing Paywalls&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Link</th></tr></thead><tbody><tr><td>Archive.is</td><td><a href="https://archive.is/" target="_blank" rel="noreferrer">archive.is</a></td></tr><tr><td>Archive.ph</td><td><a href="https://archive.ph/" target="_blank" rel="noreferrer">archive.ph</a></td></tr><tr><td>12ft.io</td><td><a href="https://12ft.io/" target="_blank" rel="noreferrer">12ft.io</a></td></tr><tr><td>PaywallHub</td><td><a href="https://paywallhub.com/" target="_blank" rel="noreferrer">paywallhub.com</a></td></tr><tr><td>Internet Archive</td><td><a href="https://archive.org/" target="_blank" rel="noreferrer">archive.org</a></td></tr></tbody></table><h3 id="privacy-friendly-frontends" tabindex="-1">Privacy-Friendly Frontends <a class="header-anchor" href="#privacy-friendly-frontends" aria-label="Permalink to &quot;Privacy-Friendly Frontends&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Service</th><th>Alternative</th></tr></thead><tbody><tr><td>TikTok</td><td><a href="https://github.com/pablouser1/ProxiTok/wiki/Public-instances#clearnet" target="_blank" rel="noreferrer">ProxiTok Instances</a></td></tr><tr><td>YouTube</td><td><a href="https://docs.invidious.io/instances/" target="_blank" rel="noreferrer">Invidious Instances</a></td></tr></tbody></table><h3 id="summary-tools" tabindex="-1">Summary Tools <a class="header-anchor" href="#summary-tools" aria-label="Permalink to &quot;Summary Tools&quot;">​</a></h3><ul><li><a href="https://smmry.com/" target="_blank" rel="noreferrer">SMMRY</a></li><li><a href="https://quillbot.com/summarize/" target="_blank" rel="noreferrer">QuillBot Summarizer</a></li><li><a href="/ai-ml/">AI Resources</a></li></ul><h2 id="security-reminders" tabindex="-1">Security Reminders <a class="header-anchor" href="#security-reminders" aria-label="Permalink to &quot;Security Reminders&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">When Consuming Shared Content</p><ul><li><strong>Trust cautiously</strong> - Always double-check URLs</li><li><strong>Use virtual environments</strong> - Consider <a href="https://vm.irregularchat.com/" target="_blank" rel="noreferrer">Kasm</a> for untrusted content</li><li><strong>Scan files</strong> - Use <a href="https://www.virustotal.com/gui/home/upload" target="_blank" rel="noreferrer">VirusTotal</a> before opening</li><li><strong>Report issues</strong> - Spot a vulnerability? Report it immediately with context</li></ul></div><hr><p><em>This wiki is continually evolving. Use the navigation, search bar, or links above to explore. Logged-in users can edit and create pages to contribute to our collective knowledge.</em></p>',26)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
